import { CloseEditLectureModalComponent } from 'app/lecture/close-edit-lecture-dialog/close-edit-lecture-modal.component';

/**
 * Route guard that prevents the user from accidentally leaving the lecture edit page with unsaved changes.
 *
 * The user is only warned if the dismiss warning is active ({@link LectureUpdateComponent.shouldDisplayDismissWarning})
 * and if there are actual changes to the title or period section ({@link LectureUpdateComponent.isChangeMadeToTitleOrPeriodSection}).
 * In that case a confirmation dialog is opened and the guard resolves to the user's decision.
 *
 * @param component the {@link LectureUpdateComponent} that is about to be left
 * @param currentRoute the current route snapshot
 * @param currentState the current router state snapshot
 * @param nextState the next router state snapshot
 * @return true if navigation is allowed, otherwise an Observable resolving to the user's decision
 */
export const hasLectureUnsavedChangesGuard = (
    component: LectureUpdateComponent,
    currentRoute: ActivatedRouteSnapshot,
    currentState: RouterStateSnapshot,
    nextState: RouterStateSnapshot,
): MaybeAsync<GuardResult> => {
    const modalService = inject(NgbModal);

    if (!component.shouldDisplayDismissWarning) {
        return true;
    }

    if (!component.isChangeMadeToTitleOrPeriodSection) {
        return true;
    }

    const modalRef = modalService.open(CloseEditLectureModalComponent, { size: 'lg', backdrop: 'static' });
    return from(modalRef.result) as Observable<boolean>;
};
